/** Read-only verification of the coordinator-provided local hosted-archive restore. */
import {writeFile} from 'node:fs/promises'
import {inspectRecovered,connect,check,canonical,digest} from './m74-security-recovery'
import {inventory,PROJECT} from '../../tools/staging/m74-common'
const database='m74_security_hosted_20260915c1',port=55472
const backupPath='.superpowers/m74-hosted-backup-candidate1.json',restorePath='.superpowers/m74-hosted-restore-candidate1.json',output='.superpowers/m74-security-hosted-recovery-candidate1.json'
const backupBytes=await Bun.file(backupPath).bytes(),restoreBytes=await Bun.file(restorePath).bytes(),backup=JSON.parse(Buffer.from(backupBytes).toString()),restore=JSON.parse(Buffer.from(restoreBytes).toString())
check(backup.schemaVersion===16&&restore.schemaVersion===16&&restore.database===database&&restore.port===port&&backup.project===PROJECT&&restore.project===PROJECT,'exact provided restore target')
check(backup.archiveSha256===restore.archiveSha256&&backup.dumpSha256===restore.dumpSha256,'backup/restore byte pins')
const db=connect(database,port)
try{check(canonical(await db.transaction(tx=>inventory(tx)))===canonical(restore.inventory),'actual restored inventory matches receipt');for(const key of Object.keys(backup.inventory).filter(k=>k!=='defaultAcls'))check(canonical(backup.inventory[key])===canonical(restore.inventory[key]),'backup/restore inventory '+key);for(const i of [backup.inventory,restore.inventory])check(!i.defaultAcls.some((r:any)=>r.schema==='*'||r.schema==='neuvetra'),'no global/application default ACL');}finally{await db.close()}
const measured=await inspectRecovered(database,port)
check(canonical(measured.recoveryManifest)===canonical(backup.recoveryManifest)&&canonical(measured.recoveryManifest)===canonical(restore.recoveryManifest),'independently rebuilt content matches both receipts')
check(measured.gasVersions>0&&measured.methodDownloads>0&&measured.legacyDownloads>0,'populated gas and legacy runtime reads')
const receipt={status:'m74_independent_recovery_passed',project:PROJECT,schemaVersion:16,port,database,createdAt:new Date().toISOString(),archiveSha256:backup.archiveSha256,dumpSha256:backup.dumpSha256,backupReceiptSha256:digest(backupBytes),restoreReceiptSha256:digest(restoreBytes),reviewerId:'/root/m74_cto',applicationReadsAndDownloadsVerified:true,m73CalculationReplayVerified:true,legacyDownloadsVerified:true,noMutationVerified:measured.noMutationVerified,recoveryManifest:measured.recoveryManifest,evidence:{byteChecks:measured.byteChecks,gasVersions:measured.gasVersions,methodDownloads:measured.methodDownloads,legacyDownloads:measured.legacyDownloads,runtimeNoClaimDenied:measured.runtimeNoClaimDenied},reviewScope:'Independent local reconstruction of actual hosted application archive; no host access, no DPAPI decrypt, no provider/Auth recovery claim.'}
await writeFile(output,JSON.stringify(receipt,null,2)+'\n',{flag:'wx'})
console.log(JSON.stringify({status:receipt.status,receipt:output,receiptSha256:digest(await Bun.file(output).bytes()),...receipt.evidence,contentEntries:receipt.recoveryManifest.entries.length}))

/** Independent native security challenges. Writes only a newly created local clone. */
import {test,expect,beforeAll,afterAll} from 'bun:test'
import {connect,child,cleanEnv,canonical,check,digest} from './m74-security-recovery'
import {inventory,NEW_TABLES} from '../../tools/staging/m74-common'
import {HostedWorkspaceDatabase,readMobileDiesel,saveMobileDiesel,m74Hash,m74CalculationHashPayload,m74ContentPayload,m74VersionHashPayload,m74Export} from '../../packages/neuvetra-database/src/index'
import {createM74Authority} from '../../apps/site-api/src/calculation/m74-authority'
const native=process.env.M74_SECURITY_NATIVE==='enabled'?test:test.skip
const sourceName='m74_author_backend_20260915c',name='m74_security_native_'+Date.now(),pg='C:/Users/nimab/Neuvetra/m63-runtime/pgsql/bin/'
let db:any,runtime:any,source:any,sourceBefore:any,baseline:any,register:any,actor:string,company:string,otherActor:string,member:string,version:any,worksheet:any,database:any
const authority=createM74Authority()
async function refused(p:Promise<unknown>,code?:string){let failure:any;try{await p}catch(e){failure=e}expect(failure).toBeDefined();if(code)expect(failure.code).toBe(code)}
const input=(v=version,patch:any={})=>({...v.activity,binding:register.sources.find((s:any)=>s.binding.sourceId===v.activity.binding.sourceId).binding,...patch,expectedVersionId:v.id,expectedVersionSha256:v.versionSha256,correctionReason:'Independent security challenge',idempotencyKey:crypto.randomUUID()})
async function rollback(fn:(tx:any)=>Promise<void>){try{await db.transaction(async(tx:any)=>{await fn(tx);throw Error('independent_expected_rollback')})}catch(e){expect((e as Error).message).toBe('independent_expected_rollback')}expect(canonical(await db.transaction((tx:any)=>inventory(tx)))).toBe(canonical(baseline))}
beforeAll(async()=>{if(process.env.M74_SECURITY_NATIVE!=='enabled')return;source=connect(sourceName);sourceBefore=await source.transaction((tx:any)=>inventory(tx));const dump=await child([pg+'pg_dump.exe','--format=custom','--no-password','--schema=neuvetra','--schema=auth'],undefined,cleanEnv(sourceName));const admin=connect('postgres');try{await admin.exec('create database '+name+' template template0')}finally{await admin.close()};await child([pg+'pg_restore.exe','--exit-on-error','--single-transaction','--no-password','--dbname='+name],dump,cleanEnv(name));db=connect(name);runtime=connect(name,55463,'neuvetra_runtime');database=new(HostedWorkspaceDatabase as any)(runtime,'abcdefghijklmnopqrst');const rows=(await db.query("select h.company_id,m.user_id from neuvetra.mobile_diesel_heads h join neuvetra.company_members m on m.company_id=h.company_id where m.role='owner' limit 1")).rows;company=rows[0].company_id;actor=rows[0].user_id;otherActor=(await db.query('select user_id from neuvetra.company_members where company_id<>$1 limit 1',[company])).rows[0].user_id;member=(await db.query("select user_id from neuvetra.company_members where company_id=$1 and role='member' limit 1",[company])).rows[0].user_id;register=await database.findMobileDiesel(actor,company,authority);worksheet=register.worksheets.find((w:any)=>w.versions.length===1);version=worksheet.versions[0];baseline=await db.transaction((tx:any)=>inventory(tx));expect(canonical(baseline)).toBe(canonical(sourceBefore))},30000)
afterAll(async()=>{if(!source)return;expect(canonical(await source.transaction((tx:any)=>inventory(tx)))).toBe(canonical(sourceBefore));await Bun.write(`.tmp/${name}-receipt.json`,JSON.stringify({status:'m74_independent_native_security_completed',createdAt:new Date().toISOString(),database:name,sourceReadOnly:sourceName,sourceUnchanged:true,restoredCloneUnchanged:canonical(await db.transaction((tx:any)=>inventory(tx)))===canonical(baseline),hostedEvidence:false})+'\n');await runtime.close();await db.close();await source.close()})
native('all nine mobile tables enforce anonymous and other-tenant RLS and deny direct writes',async()=>{
 for(const who of [null,otherActor])await runtime.transaction(async(tx:any)=>{if(who)await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[who]);for(const table of NEW_TABLES){expect((await tx.query(`select * from neuvetra.${table} where company_id=$1`,[company])).rows).toEqual([])}})
 for(const table of NEW_TABLES)await refused(runtime.transaction(async(tx:any)=>{await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[actor]);await tx.query(`delete from neuvetra.${table} where false`)}), '42501')
 expect(await database.findMobileDiesel(otherActor,company,authority)).toBeNull()
})
native('direct RPC refuses other tenant, ordinary member, missing claim and forged numerical result',async()=>{
 for(const who of [null,otherActor,member])await refused(runtime.transaction(async(tx:any)=>{if(who)await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[who]);await tx.query('select neuvetra.save_mobile_diesel($1,$2,$3::text::jsonb,$4::text::jsonb)',[company,version.worksheetId,JSON.stringify(input()),JSON.stringify(version.calculation)])}), '42501')
 await refused(runtime.transaction(async(tx:any)=>{await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[actor]);await tx.query('select neuvetra.save_mobile_diesel($1,$2,$3::text::jsonb,$4::text::jsonb)',[company,version.worksheetId,JSON.stringify(input(version,{quantityGallons:'123.000',fuelDiscrepancyReason:'Independent deliberate mismatch'})),JSON.stringify(version.calculation)])}), '22023')
})
native('membership deletion and staging revocation apply at the database boundary',async()=>{
 for(const revoke of ['delete from neuvetra.company_members where company_id=$1 and user_id=$2','update neuvetra.staging_access set active=false where company_id=$1 and user_id=$2'])await rollback(async tx=>{await tx.query(revoke,[company,actor]);await tx.exec('set local role neuvetra_runtime');await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[actor]);expect((await tx.query('select neuvetra.m74_lock($1,false) allowed',[company])).rows[0].allowed).toBe(false);expect(await readMobileDiesel(tx,company,authority)).toBeNull()})
})
native('immutable vehicle identity and cross-stream fuel or mileage evidence cannot be reused',async()=>{
 const other=register.worksheets.find((w:any)=>w.worksheetId!==worksheet.worksheetId).versions.at(-1)
 for(const patch of [{vehicle:{...version.activity.vehicle,assetId:other.activity.vehicle.assetId}},{fuelStatement:other.activity.fuelStatement,fuelDiscrepancyReason:'Independent duplicate evidence attempt'},{mileageStatement:other.activity.mileageStatement,mileageDiscrepancyReason:'Independent duplicate evidence attempt'}]){
  await refused(database.saveMobileDiesel(actor,company,version.worksheetId,input(version,patch),authority),'23505')
 }
 expect(canonical(await db.transaction((tx:any)=>inventory(tx)))).toBe(canonical(baseline))
})
native('coordinated wrong arithmetic with recomputed content/version/export/audit hashes still fails Python replay',async()=>{
 const v=structuredClone(version);v.calculation.total.unrounded='1';v.calculation.total.display='1.0000';v.calculation.resultSha256=m74Hash(m74CalculationHashPayload(v.calculation));v.contentSha256=m74Hash(m74ContentPayload(v));v.versionSha256=m74Hash(m74VersionHashPayload(v))
 await rollback(async tx=>{await tx.exec("set local session_replication_role='replica'");await tx.query('update neuvetra.mobile_diesel_versions set payload=$2::text::jsonb,content_sha256=$3,version_sha256=$4,export_text=$5 where id=$1',[v.id,JSON.stringify(v),v.contentSha256,v.versionSha256,m74Export(v)]);await tx.query("update neuvetra.mobile_diesel_audit set record_sha256=$2 where kind='save' and record_id=$1",[v.id,v.versionSha256]);await tx.exec('set local role neuvetra_runtime');await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[actor]);await refused(readMobileDiesel(tx,company,authority))})
})
native('historical reservation removal and statement text corruption fail closed; normal immutability cannot be bypassed',async()=>{
 await expect(db.query('delete from neuvetra.mobile_diesel_evidence_reservations where company_id=$1',[company])).rejects.toThrow()
 for(const sql of ["delete from neuvetra.mobile_diesel_evidence_reservations where evidence_key=(select evidence_key from neuvetra.mobile_diesel_evidence_reservations where company_id=$1 limit 1)","update neuvetra.mobile_diesel_mileage_statements set statement_text=statement_text||'corrupt' where company_id=$1"])await rollback(async tx=>{await tx.exec("set local session_replication_role='replica'");await tx.query(sql,[company]);await tx.exec('set local role neuvetra_runtime');await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[actor]);await refused(readMobileDiesel(tx,company,authority))})
})

import {test,expect} from 'bun:test'
import {validateUpgradeGate} from '../../tools/staging/m74-upgrade'
import {PROJECT,MIGRATION} from '../../tools/staging/m74-common'
import {canonical,digest} from './m74-security-recovery'
// Self-contained synthetic gate. Actual recovery observations are separate receipts.
const now=Date.parse('2026-09-16T00:00:00Z'),when=(offset=0)=>new Date(now+offset).toISOString()
async function fixture(){
 const manifest=(schemaVersion:number,tables:string[])=>{const entries=tables.map(table=>({table,id:'fixture-'+table,part:table.endsWith('_versions')?'calculation':table.endsWith('_reports')?'html':'statement',sha256:digest('synthetic'),byteLength:9}));return {profile:'neuvetra.m74.recovery-content.v1',schemaVersion,entries,sha256:digest(canonical(entries))}}
 const r:any={status:'m74_exact_application_archive_restored',project:PROJECT,schemaVersion:16,database:'m74_security_fixture',archiveSha256:'a'.repeat(64),dumpSha256:'b'.repeat(64),inventory:{tables:[{name:'stationary_gas_versions',count:1,sha256:'c'.repeat(64),rowHashes:['d'.repeat(64)]}],metadata:{functions:'e'.repeat(64)},catalogRowHashes:{functions:['f'.repeat(64)]},roles:[{rolname:'neuvetra_runtime',rolsuper:false}],memberships:[],defaultAcls:[]},recoveryManifest:manifest(16,['stationary_gas_versions','stationary_gas_reports']),applicationRowsAndCatalogExact:true,runtimeRoleFlagsExact:true,allRoleFlagsAndMembershipsExact:true,applicationDefaultAclsExact:true,runtimeNoClaimDenied:true,runtimeExistingActorReadPassed:true,recoveryContentExact:true}
 const content=manifest(17,['mobile_diesel_fuel_statements','mobile_diesel_mileage_statements','mobile_diesel_versions','mobile_diesel_reports'])
 const f:any={status:'m74_schema17_forward_recovery_review_passed',reviewedMigrationHash:MIGRATION,schemaVersion:17,populatedMobileRecoveryVerified:true,m73AndLegacyPreserved:true,runtimeReplayAndDownloadsVerified:true,noMutationVerified:true,sourceContentManifest:content,restoredContentManifest:structuredClone(content)}
 const restore={...r,createdAt:when(-2000),sourceBackupCreatedAt:when(-3000),port:55472},backup={status:'m74_encrypted_application_backup',project:PROJECT,schemaVersion:16,createdAt:when(-3000),archiveSha256:r.archiveSha256,dumpSha256:r.dumpSha256,inventory:structuredClone(r.inventory),recoveryManifest:structuredClone(r.recoveryManifest)}
 const gate={status:'m74_independent_operator_gate_passed',project:PROJECT,createdAt:when(),reviewedMigrationHash:MIGRATION,reviewedCommit:'c'.repeat(40),maintenanceConfirmed:true,maintenanceObservedAt:when(),schema17ForwardRecoveryReviewed:true,providerRecoveryExclusionAccepted:true,operatorId:'fixture-operator',independentReviewerId:'fixture-independent',restoreReceiptSha256:'a'.repeat(64)}
 const recovery={status:'m74_independent_recovery_passed',createdAt:when(-1000),project:PROJECT,schemaVersion:16,port:55472,database:r.database,archiveSha256:r.archiveSha256,dumpSha256:r.dumpSha256,restoreReceiptSha256:gate.restoreReceiptSha256,reviewerId:gate.independentReviewerId,applicationReadsAndDownloadsVerified:true,m73CalculationReplayVerified:true,legacyDownloadsVerified:true,noMutationVerified:true,recoveryManifest:structuredClone(r.recoveryManifest)}
 const forward={...f,reviewerId:gate.independentReviewerId,createdAt:when(-4000)}
 return {gate,backup,restore,recovery,forward}
}
const run=(v:Awaited<ReturnType<typeof fixture>>)=>validateUpgradeGate(v.gate,v.backup,v.restore,v.recovery,v.forward,now)
test('positive synthetic gate and precise maintenance/backup age boundaries',async()=>{
 const v=await fixture();expect(()=>run(v)).not.toThrow();v.gate.maintenanceObservedAt=when(-899999);expect(()=>run(v)).not.toThrow();v.gate.maintenanceObservedAt=when(-900000);expect(()=>run(v)).toThrow()
 const w=await fixture();w.backup.createdAt=when(-14399999);w.restore.sourceBackupCreatedAt=w.backup.createdAt;expect(()=>run(w)).not.toThrow();w.backup.createdAt=when(-14400000);w.restore.sourceBackupCreatedAt=w.backup.createdAt;expect(()=>run(w)).toThrow()
})
test('independent recovery field failures cannot substitute for actual replay/download observations',async()=>{
 for(const key of ['applicationReadsAndDownloadsVerified','m73CalculationReplayVerified','legacyDownloadsVerified','noMutationVerified'])for(const value of [undefined,false,'true',1]){const v=await fixture();(v.recovery as any)[key]=value;expect(()=>run(v)).toThrow()}
 for(const key of ['schemaVersion','port','database','archiveSha256','dumpSha256','restoreReceiptSha256','reviewerId']){const v=await fixture();delete (v.recovery as any)[key];expect(()=>run(v)).toThrow()}
})
test('full exact content detects omissions, null-to-zero changes and duplicate entry substitutions',async()=>{
 for(const mutate of [(m:any)=>m.entries.pop(),(m:any)=>{m.entries[0].sha256=digest('0')},(m:any)=>{m.entries[1]=structuredClone(m.entries[0])}]){const v=await fixture();mutate(v.recovery.recoveryManifest);v.recovery.recoveryManifest.sha256=digest(canonical(v.recovery.recoveryManifest.entries));expect(()=>run(v)).toThrow()}
})
test('schema17 forward recovery requires both evidence dimensions, calculation and captured report',async()=>{
 for(const table of ['mobile_diesel_fuel_statements','mobile_diesel_mileage_statements','mobile_diesel_versions','mobile_diesel_reports']){const v=await fixture();for(const k of ['sourceContentManifest','restoredContentManifest']){const m=(v.forward as any)[k];m.entries=m.entries.filter((e:any)=>e.table!==table);m.sha256=digest(canonical(m.entries))}expect(()=>run(v)).toThrow()}
 for(const field of ['populatedMobileRecoveryVerified','m73AndLegacyPreserved','runtimeReplayAndDownloadsVerified','noMutationVerified']){const v=await fixture();(v.forward as any)[field]=false;expect(()=>run(v)).toThrow()}
})
test('freshness cannot rescue wrong state, altered old functions, unsafe permissions or reordered authority',async()=>{
 const changes:Array<(v:any)=>void>=[v=>v.backup.schemaVersion=17,v=>v.restore.port=55463,v=>v.gate.reviewedMigrationHash='f'.repeat(64),v=>v.gate.maintenanceConfirmed=false,v=>v.gate.operatorId=v.gate.independentReviewerId,v=>v.recovery.createdAt=when(-2001),v=>v.forward.createdAt=when(1),v=>v.restore.inventory.roles[0].rolsuper=!v.restore.inventory.roles[0].rolsuper,v=>v.restore.inventory.catalogRowHashes.functions.push('f'.repeat(64)),v=>v.restore.inventory.defaultAcls.push({schema:'*'}),v=>v.restore.inventory.tables[0].rowHashes.push('f'.repeat(64))]
 for(const [index,change] of changes.entries()){const v=await fixture();change(v);let refused=false;try{run(v)}catch{refused=true}expect(refused,'mutation '+index).toBe(true)}
})

/** Independent reviewer. Local synthetic reads and new m74_security_* clones only. */
import {createHash} from 'node:crypto'
import {mkdir,writeFile} from 'node:fs/promises'
import {resolve} from 'node:path'
import {createPostgresConnection,HostedWorkspaceDatabase} from '../../packages/neuvetra-database/src/index'
import {createM73Authority} from '../../apps/site-api/src/calculation/m73-authority'
import {createM74Authority} from '../../apps/site-api/src/calculation/m74-authority'
import {createM73Routes} from '../../apps/site-api/src/workspace/m73-routes'
import {createM74Routes} from '../../apps/site-api/src/workspace/m74-routes'
import {inventory,PROJECT,MIGRATION} from '../../tools/staging/m74-common'
import {createApplicationBundle} from '../../tools/staging/m74-backup'
import {applyExact17} from '../../tools/staging/m74-apply'
export const digest=(v:string|Uint8Array)=>createHash('sha256').update(v).digest('hex')
// Deliberately separate implementation from the operator manifest builder.
export function canonical(v:any):string {if(v===null||typeof v!=='object')return JSON.stringify(v);if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}'}
export function check(v:unknown,label:string):asserts v {if(!v)throw Error('Independent recovery check: '+label)}
export const connect=(name:string,port=55463,role=port===55472?'supabase_admin':'m63_test_admin')=>createPostgresConnection(`postgres://${role}@127.0.0.1:${port}/${name}`,{tls:false,maxConnections:1})
export async function rebuild(db:any,schemaVersion:16|17){
 const entries:any[]=[];let checks=0
 const add=(table:string,id:string,part:string,content:string|Uint8Array,hash?:string,length?:number)=>{const b=typeof content==='string'?Buffer.from(content,'utf8'):content;const sha256=digest(b);check(hash===undefined||hash===sha256,table+' content hash');check(length===undefined||Number(length)===b.byteLength,table+' byte length');checks+=2;entries.push({table,id,part,sha256,byteLength:b.byteLength})}
 for(const table of ['electricity_sources','worksheet_reports','source_worksheet_reports','annual_electricity_reports','annual_evidence_reports']){
  const source=table==='electricity_sources';for(const r of(await db.query(`select id,encode(${source?'original_bytes':'report_bytes'},'hex') bytes,${source?'sha256':'report_sha256'} hash,${source?'byte_length':'report_byte_length'} size from neuvetra.${table}`)).rows)add(table,r.id,'download',Buffer.from(r.bytes,'hex'),r.hash,r.size)
 }
 const methods=['stationary_gas',...(schemaVersion===17?['mobile_diesel']:[])]
 for(const table of ['stationary_gas_statements',...(schemaVersion===17?['mobile_diesel_fuel_statements','mobile_diesel_mileage_statements']:[])])for(const r of(await db.query(`select * from neuvetra.${table}`)).rows){add(table,r.id,'statement',r.statement_text,r.statement_sha256);add(table,r.id,'metadata',canonical(r.payload))}
 for(const table of ['corporate_inventory_versions',...methods.map(m=>m+'_versions')])for(const r of(await db.query(`select * from neuvetra.${table}`)).rows){add(table,r.id,'export',r.export_text);if(table!=='corporate_inventory_versions'){check(Object.hasOwn(r.payload,'calculation'),'explicit calculation/null');add(table,r.id,'calculation',canonical(r.payload.calculation))}}
 for(const table of methods.map(m=>m+'_reports'))for(const r of(await db.query(`select * from neuvetra.${table}`)).rows){add(table,r.id,'html',r.payload.html,r.payload.htmlSha256,r.payload.htmlByteLength);add(table,r.id,'snapshot',r.payload.snapshotJson,r.payload.snapshotSha256)}
 entries.sort((a,b)=>canonical(a).localeCompare(canonical(b)))
 return {manifest:{profile:'neuvetra.m74.recovery-content.v1',schemaVersion,entries,sha256:digest(canonical(entries))},byteChecks:checks}
}
export async function inspectRecovered(name:string,port=55463){
 const db=connect(name,port),runtime=connect(name,port,'neuvetra_runtime');let downloads=0,gasVersions=0,mobileVersions=0,legacyDownloads=0
 try{
  const schemaVersion=Number((await db.query('select count(*) n from neuvetra.schema_migrations')).rows[0]!.n) as 16|17;check([16,17].includes(schemaVersion),'schema')
  const before=await db.transaction(tx=>inventory(tx)),rebuilt=await db.transaction(tx=>rebuild(tx,schemaVersion));const target=(await db.query('select project_ref from neuvetra.staging_target')).rows[0]!.project_ref as string
  const database=new(HostedWorkspaceDatabase as any)(runtime,target)
  const actors=(await db.query("select distinct on(m.company_id) m.company_id,m.user_id from neuvetra.company_members m join neuvetra.staging_access a on a.company_id=m.company_id and a.user_id=m.user_id where a.active order by m.company_id,case m.role when 'owner' then 0 when 'admin' then 1 else 2 end,m.user_id")).rows
  for(const a of actors){
   for(const mode of ['stationary_gas',...(schemaVersion===17?['mobile_diesel']:[])]){
    const gas=mode==='stationary_gas',authority=gas?createM73Authority():createM74Authority();const reg=await database[gas?'findStationaryGas':'findMobileDiesel'](a.user_id,a.company_id,authority)
    if(!reg)continue
    const route=(gas?createM73Routes:createM74Routes)({database,authority:authority as any,origin:'https://independent.invalid',validateUser:async()=>({id:a.user_id} as any)})
    const base=`/workspace/${a.company_id}/${gas?'stationary-natural-gas':'mobile-diesel'}`
    const exact=async(path:string,expected:string)=>{const r=await route(new Request('https://independent.invalid'+path,{headers:{authorization:'Bearer independent-synthetic'}}));check(r.status===200,'download status');check(Buffer.from(await r.arrayBuffer()).equals(Buffer.from(expected)),'exact runtime download bytes');check(r.headers.get('cache-control')==='no-store','download cache');downloads++}
    for(const w of reg.worksheets){for(const v of w.versions){if(gas)gasVersions++;else mobileVersions++;const raw=(await db.query(`select export_text from neuvetra.${mode}_versions where id=$1`,[v.id])).rows[0]!
     await exact(`${base}/${w.worksheetId}/versions/${v.id}/calculation-export`,raw.export_text as string)
     for(const s of(gas?[v.statement]:[v.fuelStatement,v.mileageStatement]))if(s)await exact(`${base}/${w.worksheetId}/statements/${s.id}/download`,s.text)
